const input = $input.first().json;
const body = input.body || input;

const errors = [];
const action = body.action || 'list';

// Common validation
if (action === 'list' && !body.user_id) {
  errors.push('Missing required parameter: user_id');
}

if (action === 'get' && !body.recipe_id) {
  errors.push('Missing required parameter: recipe_id');
}

if (action === 'delete') {
  if (!body.recipe_id) {
    errors.push('Missing required parameter: recipe_id');
  }
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    action: action,
    user_id: body.user_id,
    recipe_id: body.recipe_id,
    // Pagination
    limit: body.limit || 20,
    offset: body.offset || 0,
    // Filters
    tags: body.tags,
    api_base_url: body.api_base_url || process.env.API_BASE_URL || 'http://api.torah.solutions/api'
  }
}];

const input = $input.first().json;
const prevData = $('Validate Input').first().json;

try {
  // Check for API error
  if (input.detail) {
    return [{
      json: {
        success: false,
        error: {
          code: 404,
          message: input.detail,
          status: 'NOT_FOUND'
        },
        meta: { provider: 'api', action: prevData.action }
      }
    }];
  }

  // Format based on action
  if (prevData.action === 'list') {
    const recipes = (input.recipes || []).map(r => ({
      id: r.id,
      title: r.title,
      description: r.description,
      difficulty: r.difficulty,
      prep_time: r.prep_time,
      cook_time: r.cook_time,
      servings: r.servings,
      tags: r.tags,
      average_rating: r.average_rating,
      rating_count: r.rating_count,
      created_at: r.created_at
    }));
    return [{
      json: {
        success: true,
        data: {
          recipes: recipes,
          total: input.total || recipes.length,
          limit: prevData.limit,
          offset: prevData.offset
        },
        meta: { provider: 'api', action: 'list' }
      }
    }];
  } else if (prevData.action === 'get') {
    return [{
      json: {
        success: true,
        data: {
          recipe: {
            id: input.id,
            title: input.title,
            description: input.description,
            difficulty: input.difficulty,
            prep_time: input.prep_time,
            cook_time: input.cook_time,
            servings: input.servings,
            ingredients: input.ingredients,
            instructions: input.instructions,
            tags: input.tags,
            nutrition: input.nutrition,
            source: input.source,
            is_public: input.is_public,
            language: input.language,
            average_rating: input.average_rating,
            rating_count: input.rating_count,
            created_at: input.created_at,
            updated_at: input.updated_at
          }
        },
        meta: { provider: 'api', action: 'get' }
      }
    }];
  } else if (prevData.action === 'delete') {
    return [{
      json: {
        success: true,
        data: {
          message: input.message || 'Recipe deleted'
        },
        meta: { provider: 'api', action: 'delete' }
      }
    }];
  }

  return [{ json: { success: true, data: input, meta: { provider: 'api' } } }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to process API response: ' + e.message,
        status: 'PROCESS_ERROR'
      },
      meta: { provider: 'api' }
    }
  }];
}
